CREATE VIEW [DBO].[CUSTWRITEOFFFINANCIALREASONSSETUPENTITY] AS SELECT T1.COMPANY AS COMPANY, T1.REASON AS WRITEOFFREASON, T1.DESCRIPTION AS WRITEOFFDESCRIPTION, T1.ISDEFAULT AS ISDEFAULT, T1.WRITEOFFLEDGERDIMENSION AS WRITEOFFLEDGERDIMENSION, T1.RECVERSION AS RECVERSION, T1.PARTITION AS PARTITION, T1.RECID AS RECID, T2.DISPLAYVALUE AS WRITEOFFLEDGERDIMENSIONDISPLAYVALUE, T2.RECVERSION AS RECVERSION#2, T2.PARTITION AS PARTITION#2, T2.RECID AS RECID#2 FROM CUSTWRITEOFFFINANCIALREASONSSETUP T1 LEFT OUTER JOIN DIMENSIONCOMBINATIONENTITY T2 ON(( T1.WRITEOFFLEDGERDIMENSION  =  T2.RECID)  AND ( T1.PARTITION  =  T2.PARTITION))